import React, { useEffect, useMemo, useState } from 'react';
import { Link, useNavigate, useParams } from 'react-router-dom';
import { productApi } from '../services/api';
import { useStore } from '../context/StoreContext';
import ProductCard from '../components/ProductCard';
import Chatbot from '../components/Chatbot';
import './ProductDetailsPage.css';

function formatPrice(price) {
  return `$${Number(price || 0).toLocaleString('en-US', {
    maximumFractionDigits: 2,
  })}`;
}

function ProductDetailsPage() {
  const { productId } = useParams();
  const navigate = useNavigate();

  const {
    addToCart,
    toggleWishlist,
    isInWishlist,
    addRecentlyViewed,
    showToast,
  } = useStore();

  const [product, setProduct] = useState(null);
  const [relatedProducts, setRelatedProducts] = useState([]);
  const [activeImage, setActiveImage] = useState('');
  const [activeTab, setActiveTab] = useState('overview');
  const [quantity, setQuantity] = useState(1);
  const [loading, setLoading] = useState(true);
  const [relatedLoading, setRelatedLoading] = useState(false);
  const [error, setError] = useState('');

  const currentProductId = product?.id || product?.productId || productId;
  const saved = product ? isInWishlist(currentProductId) : false;
  const stock = Number(product?.stock || 0);
  const inStock = stock > 0;

  const productImages = useMemo(() => {
    if (!product) {
      return [];
    }

    const images = [
      product.image,
      ...(Array.isArray(product.images) ? product.images : []),
      product.thumbnail,
    ].filter(Boolean);

    return [...new Set(images)];
  }, [product]);

  useEffect(() => {
    let ignore = false;

    async function loadProduct() {
      try {
        setLoading(true);
        setError('');

        const response = await productApi.getProduct(productId);
        const nextProduct = response?.product || response?.data || response;

        if (!nextProduct || !nextProduct.title) {
          throw new Error('Product not found');
        }

        if (!ignore) {
          setProduct(nextProduct);
          setActiveImage(nextProduct.image || nextProduct.images?.[0] || nextProduct.thumbnail || '');
          addRecentlyViewed(nextProduct);
        }
      } catch (err) {
        if (!ignore) {
          setError('Unable to load product details. Please try again or browse products again.');
          setProduct(null);
        }
      } finally {
        if (!ignore) {
          setLoading(false);
        }
      }
    }

    loadProduct();

    return () => {
      ignore = true;
    };
  }, [productId, addRecentlyViewed]);

  useEffect(() => {
    if (!product) {
      return undefined;
    }

    let ignore = false;

    async function loadRelated() {
      try {
        setRelatedLoading(true);

        const response = await productApi.searchProducts({
          q: product.category || product.rawCategory || product.brand || 'laptop',
          limit: 8,
          sort: 'rating',
        });

        const items = (response?.products || []).filter(
          (item) => (item.id || item.productId) !== currentProductId
        );

        if (!ignore) {
          setRelatedProducts(items.slice(0, 4));
        }
      } catch {
        if (!ignore) {
          setRelatedProducts([]);
        }
      } finally {
        if (!ignore) {
          setRelatedLoading(false);
        }
      }
    }

    loadRelated();

    return () => {
      ignore = true;
    };
  }, [product, currentProductId]);

  const handleAddToCart = () => {
    if (!product || !inStock) {
      showToast('This product is currently out of stock', 'error');
      return;
    }

    addToCart(product, quantity);
  };

  const handleBuyNow = () => {
    if (!product || !inStock) {
      showToast('This product is currently out of stock', 'error');
      return;
    }

    addToCart(product, quantity);
    navigate('/cart');
  };

  const specs = product?.specifications || {};

  if (loading) {
    return (
      <main className="product-detail-page">
        <div className="container">
          <div className="product-detail-skeleton">
            <div className="skeleton detail-skeleton-gallery" />
            <div>
              <div className="skeleton detail-skeleton-line wide" />
              <div className="skeleton detail-skeleton-line" />
              <div className="skeleton detail-skeleton-line short" />
              <div className="skeleton detail-skeleton-actions" />
            </div>
          </div>
        </div>
      </main>
    );
  }

  if (error || !product) {
    return (
      <main className="product-detail-page">
        <div className="container">
          <div className="empty-state">
            <div className="empty-state-icon">⚠️</div>
            <h3>Product not found</h3>
            <p>{error || 'The selected product could not be loaded.'}</p>
            <Link to="/products" className="btn btn-primary">
              Back to Products
            </Link>
          </div>
        </div>
      </main>
    );
  }

  return (
    <main className="product-detail-page">
      <div className="container">
        <div className="breadcrumb">
          <Link to="/">Home</Link>
          <span>›</span>
          <Link to="/products">Products</Link>
          <span>›</span>
          <span>{product.title}</span>
        </div>

        <section className="product-detail-grid">
          <div className="product-gallery-card">
            <div className="product-main-image">
              <img
                src={activeImage || product.image}
                alt={product.title}
                onError={(event) => {
                  event.currentTarget.src =
                    'https://dummyjson.com/image/600x400/eeeeee/111111?text=Tech+Store';
                }}
              />

              <div className="detail-image-badges">
                <span>DummyJSON</span>
                {Number(product.discountPercentage || 0) > 0 && (
                  <strong>-{Math.round(product.discountPercentage)}%</strong>
                )}
              </div>
            </div>

            <div className="product-thumb-row">
              {productImages.slice(0, 6).map((image) => (
                <button
                  type="button"
                  key={image}
                  className={activeImage === image ? 'active' : ''}
                  onClick={() => setActiveImage(image)}
                  aria-label="Change product image"
                >
                  <img src={image} alt={`${product.title} thumbnail`} />
                </button>
              ))}
            </div>
          </div>

          <div className="product-info-card">
            <div className="product-info-top">
              <span className="badge badge-primary">{product.category || 'Technology'}</span>
              <span className={inStock ? 'badge badge-success' : 'badge badge-danger'}>
                {inStock ? `In Stock ${stock}` : 'Out of Stock'}
              </span>
            </div>

            <h1>{product.title}</h1>

            <div className="detail-rating-row">
              <span className="detail-stars">
                {'★'.repeat(Math.max(1, Math.round(product.rating || 4))).slice(0, 5)}
                <small>{'☆'.repeat(Math.max(0, 5 - Math.round(product.rating || 4))).slice(0, 5)}</small>
              </span>
              <strong>{Number(product.rating || 0).toFixed(1)}</strong>
              <span>({product.reviewCount || product.reviews?.length || 24} reviews)</span>
            </div>

            <p className="detail-description">{product.description}</p>

            <div className="detail-price-row">
              <div>
                <strong>{formatPrice(product.price)}</strong>
                {Number(product.discountPercentage || 0) > 0 && (
                  <span>
                    {formatPrice(
                      Number(product.price || 0) /
                        (1 - Number(product.discountPercentage || 0) / 100)
                    )}
                  </span>
                )}
              </div>

              <button
                type="button"
                className={saved ? 'detail-wishlist active' : 'detail-wishlist'}
                onClick={() => toggleWishlist(product)}
              >
                {saved ? '♥ Saved' : '♡ Wishlist'}
              </button>
            </div>

            <div className="detail-option-card">
              <div>
                <strong>Quantity</strong>
                <span>Choose quantity before adding to cart</span>
              </div>

              <div className="detail-quantity">
                <button
                  type="button"
                  onClick={() => setQuantity((value) => Math.max(1, value - 1))}
                >
                  −
                </button>
                <span>{quantity}</span>
                <button
                  type="button"
                  onClick={() => setQuantity((value) => Math.min(stock || 99, value + 1))}
                >
                  +
                </button>
              </div>
            </div>

            <div className="detail-action-row">
              <button
                type="button"
                className="btn btn-primary"
                onClick={handleAddToCart}
                disabled={!inStock}
              >
                Add to Cart
              </button>

              <button
                type="button"
                className="btn btn-secondary"
                onClick={handleBuyNow}
                disabled={!inStock}
              >
                Buy Now
              </button>
            </div>

            <div className="detail-trust-grid">
              <div>🔒 Secure checkout</div>
              <div>🚚 Fast delivery</div>
              <div>🔄 Easy returns</div>
              <div>🛡️ Standard warranty</div>
            </div>
          </div>
        </section>

        <section className="detail-tabs-section">
          <div className="detail-tabs">
            {['overview', 'specifications', 'reviews', 'ai'].map((tab) => (
              <button
                type="button"
                key={tab}
                className={activeTab === tab ? 'active' : ''}
                onClick={() => setActiveTab(tab)}
              >
                {tab === 'ai' ? 'AI Summary' : tab}
              </button>
            ))}
          </div>

          <div className="detail-tab-content">
            {activeTab === 'overview' && (
              <div className="detail-overview">
                <h2>Product Overview</h2>
                <p>{product.description}</p>

                <div className="detail-overview-grid">
                  <div>
                    <span>Brand</span>
                    <strong>{product.brand || 'Tech Brand'}</strong>
                  </div>
                  <div>
                    <span>Category</span>
                    <strong>{product.category || 'Technology'}</strong>
                  </div>
                  <div>
                    <span>Availability</span>
                    <strong>{product.availability || 'In stock'}</strong>
                  </div>
                  <div>
                    <span>Source</span>
                    <strong>DummyJSON API</strong>
                  </div>
                </div>
              </div>
            )}

            {activeTab === 'specifications' && (
              <div className="detail-spec-table">
                {Object.entries(specs).length > 0 ? (
                  Object.entries(specs).map(([key, value]) => (
                    <div key={key}>
                      <span>{key}</span>
                      <strong>{String(value || 'Not available')}</strong>
                    </div>
                  ))
                ) : (
                  <p>No detailed specifications available for this DummyJSON product.</p>
                )}
              </div>
            )}

            {activeTab === 'reviews' && (
              <div className="detail-reviews">
                <div className="review-summary-card">
                  <strong>{Number(product.rating || 4.5).toFixed(1)}</strong>
                  <span>Average rating</span>
                  <p>AI sentiment summary: mostly positive based on rating and review tone.</p>
                </div>

                {(product.reviews || []).length > 0 ? (
                  product.reviews.map((review, index) => (
                    <article className="review-card" key={`${review.reviewerName || 'user'}-${index}`}>
                      <div>
                        <strong>{review.reviewerName || 'Verified Buyer'}</strong>
                        <span>{review.date ? new Date(review.date).toLocaleDateString() : 'Recent'}</span>
                      </div>
                      <p>{review.comment || 'Good product experience.'}</p>
                      <small>{'★'.repeat(Math.round(review.rating || 4))}</small>
                    </article>
                  ))
                ) : (
                  <article className="review-card">
                    <div>
                      <strong>Verified Buyer</strong>
                      <span>Recent</span>
                    </div>
                    <p>This product has good value, clear images and useful information for comparison.</p>
                    <small>★★★★★</small>
                  </article>
                )}
              </div>
            )}

            {activeTab === 'ai' && (
              <div className="detail-ai-box">
                <span>🤖</span>
                <div>
                  <h2>AI Product Summary</h2>
                  <p>
                    This product is recommended for users looking for {product.category || 'technology'} products
                    from {product.brand || 'a known brand'}. It has a rating of{' '}
                    {Number(product.rating || 4.5).toFixed(1)} and is currently{' '}
                    {inStock ? 'available in stock' : 'not available'}.
                  </p>
                  <button
                    type="button"
                    className="btn btn-primary"
                    onClick={() => navigate(`/ai-recommendations?query=${encodeURIComponent(product.title)}`)}
                  >
                    Get Similar AI Picks
                  </button>
                </div>
              </div>
            )}
          </div>
        </section>

        <section className="related-section">
          <div className="home-section-header">
            <div>
              <span className="section-eyebrow">Related Products</span>
              <h2>You may also like</h2>
              <p>Related products are fetched dynamically using DummyJSON categories and product similarity.</p>
            </div>
          </div>

          {relatedLoading ? (
            <div className="related-grid">
              {Array.from({ length: 4 }).map((_, index) => (
                <div className="skeleton related-skeleton" key={index} />
              ))}
            </div>
          ) : (
            <div className="related-grid">
              {relatedProducts.map((item) => (
                <ProductCard key={item.id || item.productId} product={item} compact />
              ))}
            </div>
          )}
        </section>
      </div>

      <Chatbot floating />
    </main>
  );
}

export default ProductDetailsPage;
